from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return parity (0 or 1) of each element of xs, computed in a thread pool.

    The result is in input order, regardless of the number of workers
    or the order in which tasks complete. Does not modify xs.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4]) == [0, 1, 0, 1, 0]


def test_parities_negative() -> None:
    assert parities([-1, -2, -3]) == [1, 0, 1]


def test_parities_large_values() -> None:
    big = 10**30
    assert parities([big, big + 1]) == [0, 1]


def test_parities_preserves_order_large_input() -> None:
    xs = [(i * 7919) % 1009 for i in range(5000)]
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_repeated_runs_same_result() -> None:
    xs = list(range(-500, 500))
    expected = [parity(x) for x in xs]
    for _ in range(5):
        assert parities(xs) == expected


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 4, 3]
    parities(xs)
    assert xs == [5, 4, 3]
